onClick:
{{
  (function() {
    const data = Get_Detail_BL.data[0];

    // On prépare les infos de retour
    const paramsRetour = {
      from_page: 'Détail Bon de Livraison',
      from_id: data.ID_BL // Remplace ID_BL par le nom exact de la colonne ID de ton BL si besoin
    };

    if (data.Origine === 'Intervention' && data.ID_Intervention) {
      navigateTo('Détail Intervention', { id: data.ID_Intervention, ...paramsRetour });
    } 
    else if (data.Origine === 'Commande Client' && data.ID_COMMANDE_CLIENT) {
      navigateTo('Détail Commande', { id_commande: data.ID_COMMANDE_CLIENT, ...paramsRetour });
    } 
    else if (data.Origine === 'Location' && data.ID_Location) {
      navigateTo('Détail Location', { id_location: data.ID_Location, ...paramsRetour });
    }
  })()
}}
